<?php
declare(strict_types=1);
require_once __DIR__.'/../config/auth.php';
require_once __DIR__.'/../config/telefono.php';
require_once __DIR__.'/../config/reglas-acceso.php';
require_once __DIR__.'/../config/intensivo-transferencias.php';
$admin=page_require(['ADMIN']);
$config=require __DIR__.'/../config/database.php';
$pdo=new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$sedeClave=auth_active_sede_clave();
$sedeStmt=$pdo->prepare("SELECT id FROM sedes WHERE clave=:clave AND activo=1 LIMIT 1");$sedeStmt->execute([':clave'=>$sedeClave]);$sedeId=(string)$sedeStmt->fetchColumn();if($sedeId===''){http_response_code(422);exit('Sede activa inválida.');}
$id=$_GET['id']??$_POST['id']??'';
if(!preg_match('/^[0-9a-fA-F-]{36}$/',$id)){http_response_code(400);exit('ID de alumno inválido.');}
$stmt=$pdo->prepare("SELECT * FROM alumnos WHERE id=:id AND sede_id=:sede LIMIT 1");$stmt->execute([':id'=>$id,':sede'=>$sedeId]);$alumno=$stmt->fetch();if(!$alumno){http_response_code(404);exit('Alumno no encontrado en la sede activa.');}
$stInt=$pdo->prepare("SELECT ci.id,ci.fecha_inicio,ci.fecha_fin,cia.horario_id FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=:a AND ci.sede_id=:s AND ci.fecha_fin>=CURDATE() ORDER BY ci.fecha_inicio ASC LIMIT 1");$stInt->execute([':a'=>$id,':s'=>$sedeId]);$intensivoActual=$stInt->fetch()?:null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!auth_csrf_validate(isset($_POST['csrf'])?(string)$_POST['csrf']:null)){http_response_code(419);exit('La sesión del formulario venció. Recarga la página e inténtalo otra vez.');}
    $nombre=trim((string)($_POST['nombre']??''));$fechaNacimiento=trim((string)($_POST['fecha_nacimiento']??''));$waEntrada=trim((string)($_POST['whatsapp']??''));$waPais=strtoupper(trim((string)($_POST['whatsapp_pais']??'')));$correo=trim((string)($_POST['correo']??''));$fechaInicio=$_POST['fecha_inicio']?:null;$horario=$_POST['horario_preferido_id']?:null;$plan=$_POST['plan_actual_id']?:null;$estado=strtoupper((string)($_POST['estado_administrativo']??'PENDIENTE'));$obs=trim((string)($_POST['observaciones']??''));$historica=isset($_POST['inscripcion_historica_cubierta'])&&$_POST['inscripcion_historica_cubierta']==='1';
    if($nombre==='')exit('El nombre es obligatorio.');
    if(!in_array($estado,['ACTIVO','PENDIENTE','BAJA'],true))exit('Estado inválido.');
    try{
        if($waPais===''){
            if(telefono_es_e164((string)$alumno['whatsapp']))$whatsapp=(string)$alumno['whatsapp'];
            elseif(telefono_digitos($waEntrada)===telefono_digitos((string)$alumno['whatsapp']))$whatsapp=(string)$alumno['whatsapp'];
            else throw new InvalidArgumentException('Selecciona el país antes de cambiar un WhatsApp antiguo.');
        }else $whatsapp=telefono_normalizar($waPais,$waEntrada);
    }catch(InvalidArgumentException $e){exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}
    $pdo->beginTransaction();
    try{
        regla_bloquear_identidades_alumnos($pdo);
        $st=$pdo->prepare("SELECT sede_id,horario_preferido_id,plan_actual_id FROM alumnos WHERE id=:id AND sede_id=:s LIMIT 1 FOR UPDATE");$st->execute([':id'=>$id,':s'=>$sedeId]);$actual=$st->fetch();if(!$actual){$pdo->rollBack();http_response_code(404);exit('Alumno no encontrado en la sede activa.');}
        $dup=$pdo->prepare("SELECT nombre FROM alumnos WHERE whatsapp=:w AND id<>:id LIMIT 1");$dup->execute([':w'=>$whatsapp,':id'=>$id]);if($x=$dup->fetch()){$pdo->rollBack();exit('Ese WhatsApp ya pertenece a '.htmlspecialchars($x['nombre'],ENT_QUOTES,'UTF-8').'.');}
        if($horario){$st=$pdo->prepare("SELECT activo FROM horarios WHERE id=:id AND sede_id=:s AND regular=1 LIMIT 1 FOR UPDATE");$st->execute([':id'=>$horario,':s'=>$actual['sede_id']]);$activo=$st->fetchColumn();if($activo===false||(!(bool)$activo&&(string)$actual['horario_preferido_id']!==$horario)){$pdo->rollBack();exit('El horario seleccionado no pertenece a la sede del alumno o ya no está disponible.');}}
        if($plan){$st=$pdo->prepare("SELECT activo FROM planes WHERE id=:id AND sede_id=:s LIMIT 1 FOR UPDATE");$st->execute([':id'=>$plan,':s'=>$actual['sede_id']]);$activo=$st->fetchColumn();if($activo===false||(!(bool)$activo&&(string)$actual['plan_actual_id']!==$plan)){$pdo->rollBack();exit('El plan seleccionado no pertenece a la sede del alumno o ya no está disponible.');}}
        if($estado==='BAJA'){
            $st=$pdo->prepare("SELECT ci.fecha_inicio FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=:a AND ci.sede_id=:s AND ci.fecha_fin>=CURDATE() ORDER BY ci.fecha_inicio ASC LIMIT 1 FOR UPDATE");
            $st->execute([':a'=>$id,':s'=>$sedeId]);
            $fechaIntensivoBaja=$st->fetchColumn();
            if($fechaIntensivoBaja!==false){
                $fechaIntensivoBaja=(string)$fechaIntensivoBaja;
                if($fechaInicio===null)throw new IntensivoTransferenciaException('La fecha de inicio es obligatoria mientras el alumno siga ligado a un intensivo activo, incluso al marcarlo como baja.');
                if($fechaInicio!==$fechaIntensivoBaja)throw new IntensivoTransferenciaException('Al marcar BAJA conserva la fecha del curso intensivo actual. Si necesitas cambiarlo de curso, haz esa corrección antes de darlo de baja.');
            }
        }
        $sql="UPDATE alumnos SET nombre=?,fecha_nacimiento=?,whatsapp=?,correo=?,fecha_inicio=?,horario_preferido_id=?,plan_actual_id=?,estado_administrativo=?,observaciones=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND sede_id=?";
        $pdo->prepare($sql)->execute([$nombre,$fechaNacimiento!==''?$fechaNacimiento:null,$whatsapp,$correo!==''?$correo:null,$fechaInicio,$horario,$plan,$estado==='BAJA'?'BAJA':'PENDIENTE',$obs!==''?$obs:null,$id,$sedeId]);
        regla_marcar_inscripcion_historica($pdo,$id,$historica,$historica?'Inscripción cubierta antes de la implementación del sistema':null);
        if($estado!=='BAJA'){
            intensivo_transferir_por_fecha_edicion($pdo,$id,$sedeId,$fechaInicio,(string)$admin['id']);
            regla_recalcular_alumno($pdo,$id);
        }
        $pdo->commit();
    }catch(IntensivoTransferenciaException $e){if($pdo->inTransaction())$pdo->rollBack();exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}
    catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
    header('Location: ficha-alumno.php?id='.urlencode($id));exit;
}
$st=$pdo->prepare("SELECT id,hora_inicio,hora_fin FROM horarios WHERE sede_id=:s AND regular=1 AND (activo=1 OR id=:actual) ORDER BY hora_inicio ASC");$st->execute([':s'=>$alumno['sede_id'],':actual'=>(string)($alumno['horario_preferido_id']??'')]);$horarios=$st->fetchAll();$st=$pdo->prepare("SELECT id,nombre,sesiones_semana,precio FROM planes WHERE sede_id=:s AND (activo=1 OR id=:actual) ORDER BY precio ASC");$st->execute([':s'=>$alumno['sede_id'],':actual'=>(string)($alumno['plan_actual_id']??'')]);$planes=$st->fetchAll();
$historicaActual=regla_inscripcion_historica_cubierta($pdo,$id);
$telefono=telefono_descomponer((string)$alumno['whatsapp']);
$paises=telefono_paises();
function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar alumno</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fa;color:#172033}.contenedor{max-width:900px;margin:auto;padding:25px 20px 40px}.encabezado{margin-bottom:20px}.encabezado a{color:#2563eb;text-decoration:none}h1{margin:15px 0 5px;font-size:30px}.subtitulo{color:#64748b}.tarjeta{background:#fff;border-radius:18px;padding:25px;margin-bottom:20px;box-shadow:0 4px 15px #0000000d}label{display:block;margin-bottom:7px;font-weight:600}input,select,textarea{width:100%;padding:13px;border:1px solid #d8dee8;border-radius:10px;font-size:16px;margin-bottom:18px;background:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.telefono-grid{display:grid;grid-template-columns:minmax(180px,.8fr) minmax(0,1.2fr);gap:10px}.check{display:flex;gap:10px;align-items:flex-start;background:#f8fafc;border:1px solid #dbe4ee;border-radius:12px;padding:14px;margin:8px 0 4px}.check input{width:auto;margin:3px 0 0}.check label{margin:0}.check small{display:block;color:#64748b;font-weight:400;line-height:1.4;margin-top:4px}.hint-intensivo{display:block;color:#7c4a03;background:#fff8e8;border:1px solid #f6c85f;border-radius:10px;padding:10px 12px;margin-top:-10px;margin-bottom:18px;line-height:1.45}.botones{display:flex;gap:12px;flex-wrap:wrap}button,.boton-cancelar{border:0;border-radius:10px;padding:13px 20px;font-size:16px;text-decoration:none}button{background:#2563eb;color:#fff}.boton-cancelar{background:#e5e7eb;color:#172033}@media(max-width:650px){.grid,.telefono-grid{grid-template-columns:1fr;gap:0}.tarjeta{padding:20px}}</style></head><body><div class="contenedor"><div class="encabezado"><a href="ficha-alumno.php?id=<?=urlencode($alumno['id'])?>">← Volver a ficha</a><h1>Editar alumno</h1><div class="subtitulo"><?=e($alumno['nombre'])?></div></div><form method="post"><input type="hidden" name="csrf" value="<?=e(auth_csrf_token())?>"><input type="hidden" name="id" value="<?=e($alumno['id'])?>"><div class="tarjeta"><h2>Información personal</h2><label>Nombre</label><input name="nombre" value="<?=e($alumno['nombre'])?>" required><div class="grid"><div><label>Fecha de nacimiento</label><input type="date" name="fecha_nacimiento" value="<?=e($alumno['fecha_nacimiento'])?>"><small style="display:block;color:#64748b;margin-top:-12px;margin-bottom:18px">Opcional.</small></div><div><label>WhatsApp</label><div class="telefono-grid"><select name="whatsapp_pais" required><option value="" <?=$telefono['pais']===''?'selected':''?>>País sin verificar</option><?php foreach($paises as $iso=>$p):?><option value="<?=e($iso)?>" <?=$telefono['pais']===$iso?'selected':''?>><?=e($p['nombre'].' '.$p['codigo'])?></option><?php endforeach;?></select><input type="text" name="whatsapp" value="<?=e((string)$telefono['nacional'])?>" required inputmode="tel" placeholder="Número local / nacional"></div></div></div><label>Correo</label><input type="email" name="correo" value="<?=e($alumno['correo'])?>"></div><div class="tarjeta"><h2>Información de natación</h2><div class="grid"><div><label>Fecha de inicio</label><input type="date" name="fecha_inicio" value="<?=e($alumno['fecha_inicio'])?>"><?php if($intensivoActual):?><small class="hint-intensivo">Curso intensivo actual: <?=e(date('d/m/Y',strtotime((string)$intensivoActual['fecha_inicio'])))?>. Si cambias esta fecha a otro lunes, el sistema moverá al alumno al intensivo de esa fecha; si todavía no existe, lo creará con el mismo precio. Por seguridad no se moverá si ya tiene pago, asistencia, ausencias, reposiciones o continuidad registradas.</small><?php endif;?></div><div><label>Estado</label><select name="estado_administrativo"><option value="ACTIVO" <?=$alumno['estado_administrativo']==='ACTIVO'?'selected':''?>>ACTIVO</option><option value="PENDIENTE" <?=$alumno['estado_administrativo']==='PENDIENTE'?'selected':''?>>PENDIENTE</option><option value="BAJA" <?=$alumno['estado_administrativo']==='BAJA'?'selected':''?>>BAJA</option></select></div></div><label>Horario</label><select name="horario_preferido_id"><option value="">Sin horario</option><?php foreach($horarios as $h):?><option value="<?=e($h['id'])?>" <?=$alumno['horario_preferido_id']===$h['id']?'selected':''?>><?=e(substr($h['hora_inicio'],0,5).' — '.substr($h['hora_fin'],0,5))?></option><?php endforeach;?></select><label>Plan</label><select name="plan_actual_id"><option value="">Sin plan</option><?php foreach($planes as $p):?><option value="<?=e($p['id'])?>" <?=$alumno['plan_actual_id']===$p['id']?'selected':''?>><?=e($p['nombre'])?> — <?=e((string)$p['sesiones_semana'])?> sesiones — $<?=number_format((float)$p['precio'],0)?></option><?php endforeach;?></select><div class="check"><input type="checkbox" id="inscripcion_historica" name="inscripcion_historica_cubierta" value="1" <?=$historicaActual?'checked':''?>><label for="inscripcion_historica">Inscripción histórica ya cubierta<small>Úsalo solamente para alumnos que ya habían pagado su inscripción antes de usar este sistema. No crea ingresos ni pagos ficticios.</small></label></div></div><div class="tarjeta"><h2>Observaciones</h2><textarea name="observaciones"><?=e($alumno['observaciones'])?></textarea></div><div class="botones"><button type="submit">Guardar cambios</button><a class="boton-cancelar" href="ficha-alumno.php?id=<?=urlencode($alumno['id'])?>">Cancelar</a></div></form></div></body></html>
